package dev.nezo.burmaldaholic.client.ui.v2;

import dev.nezo.burmaldaholic.client.fx.FxSprites;
import net.minecraft.resources.Identifier;

/**
 * Sprite ids of the table UI v2 kit ({@code textures/gui/sprites/core/v2/…}, generated by {@code tools/assets/modules/ui2.mjs};
 * docs/architecture/ui-v2.md §9, D11). Every component draws a flat-colour fallback when a sprite is missing.
 */
public final class V2Sprites {
	private V2Sprites() {}

	public static Identifier v2(String path) {
		return FxSprites.sprite("v2/" + path);
	}

	public static final Identifier TOPBAR = v2("topbar");
	public static final Identifier DOCK = v2("dock");
	public static final Identifier BANNER = v2("banner");
	public static final Identifier TOAST = v2("toast");
	public static final Identifier FELT_VIGNETTE = v2("felt_vignette");
	public static final Identifier FOCUS_RING = v2("focus_ring");
	public static final Identifier KEY_HINT = v2("key_hint");
	public static final Identifier CHIP_SELECTED_RING = v2("chip_selected_ring");
	public static final Identifier CHIP_ICON = v2("chip_icon");
	public static final Identifier BALANCE = v2("balance_pill");
	public static final Identifier TITLE_PILL = v2("title_pill");
	public static final Identifier INFO_PILL = v2("info_pill");
	public static final Identifier TOTAL_PILL = v2("total_pill");

	/** Button styles; each with {@code _hover}, {@code _pressed}, {@code _disabled} variants. */
	public enum ButtonStyle {
		PRIMARY("button_primary"),
		NORMAL("button"),
		DANGER("button_danger"),
		ICON("icon_button");

		private final String base;

		ButtonStyle(String base) {
			this.base = base;
		}

		public Identifier sprite(boolean enabled, boolean hover, boolean pressed) {
			return v2(base + (!enabled ? "_disabled" : pressed ? "_pressed" : hover ? "_hover" : ""));
		}
	}

	/** Tool and TopBar icon glyphs: undo, clear, rebet, double, rules, settings, leave. */
	public static Identifier icon(String name) {
		return v2("icon/" + name);
	}

	/** Tray chip of a denomination ({@code chip_<d>}; {@code _l} = the 32² T3 size, {@code _s} = the 20² T1 size). */
	public static Identifier chip(long denom, int size) {
		return v2("chip_" + denom + (size >= 32 ? "_l" : size <= 20 ? "_s" : ""));
	}

	/** Top-down felt disc of a denomination (12² / 16²). */
	public static Identifier disc(long denom, int size) {
		return v2("felt_disc_" + denom + (size >= 16 ? "_l" : ""));
	}

	public static Identifier valuePill(ValuePill.Style s) {
		return v2(switch (s) {
			case YOU -> "value_pill_you";
			case WIN -> "value_pill_win";
			case LOSE -> "value_pill_lose";
			case PUSH -> "value_pill_push";
			case OTHER -> "value_pill";
		});
	}

	public static Identifier plate(SeatPlate.Kind k) {
		return v2(switch (k) {
			case YOU -> "plate_you";
			case ACTING -> "plate_acting";
			case OTHER -> "plate";
		});
	}

	public static Identifier stamp(dev.nezo.burmaldaholic.core.ui.v2.Stamps.Kind k) {
		return v2("stamp_" + k.name().toLowerCase(java.util.Locale.ROOT));
	}

	public static Identifier stampDot(dev.nezo.burmaldaholic.core.ui.v2.Stamps.Kind k) {
		return v2("stamp_dot_" + k.name().toLowerCase(java.util.Locale.ROOT));
	}
}
